// Class 12 Physics Unit I Chapter 1: Electric Charges and Fields (100% Exact Official NCERT Syllabus Alignment)
// High-Level Pradeep's / S.L. Arora Digital Reference Book Content & NCERT Solutions (Definition-First Prose & 3D Volumetric SVGs)

export const c12Phy1HtmlOverview = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.75; font-size: 16px;\">\n\n  <!-- QUICK GLOSSARY & BASIC DEFINITIONS CARD -->\n  <div style=\"background: rgba(255, 81, 47, 0.05); border: 1.5px solid #FF512F; border-radius: 12px; padding: 18px; margin-bottom: 25px;\">\n    <h2 class=\"text-center\" style=\"color: #FF512F; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">📖 Quick Glossary & Basic Definitions</h2>\n    <p class=\"text-center\" style=\"color: #FF512F; margin: 0 0 16px 0; font-size: 14.5px; text-align: center !important;\">Essential Core Terms for Unit I: Electric Charges and Fields</p>\n\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 12px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 4px;'>1. Electric Charge (q):</b>\n        <span style=\"color: #FFFFFF;\">Intrinsic scalar property of fundamental matter particles giving rise to electrostatic attraction or repulsion [Coulomb C].</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 4px;'>2. Quantization of Charge:</b>\n        <span style=\"color: #FFFFFF;\">The principle that net charge of any body is an integral multiple of elementary charge e: q = ±n e (e = 1.6 × 10<sup>-19</sup> C).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 4px;'>3. Coulomb's Law:</b>\n        <span style=\"color: #FFFFFF;\">Electrostatic force between two stationary point charges is proportional to product of charges &amp; inversely to square of distance: F = [1/(4πε₀)] (q₁ q₂ / r²).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 4px;'>4. Electric Field Intensity (E⃗):</b>\n        <span style=\"color: #FFFFFF;\">Electrostatic force experienced per unit positive test charge placed at a given point: E⃗ = F⃗ / q₀ [N/C or V/m].</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 4px;'>5. Electric Dipole Moment (p⃗):</b>\n        <span style=\"color: #FFFFFF;\">Vector measure of dipole strength directed from negative to positive charge: p⃗ = q (2a⃗) [C m].</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 4px;'>6. Electric Flux (Φ_E):</b>\n        <span style=\"color: #FFFFFF;\">Total number of electric field lines passing normally through a given surface: Φ_E = ∬ E⃗ · dA⃗ [N m² C⁻¹].</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 4px;'>7. Gauss's Law / Theorem:</b>\n        <span style=\"color: #FFFFFF;\">Total electric flux through any closed 3D surface equals 1/ε₀ times net charge enclosed inside: ∮ E⃗ · dA⃗ = q_enclosed / ε₀.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 4px;'>8. Electrostatic Shielding:</b>\n        <span style=\"color: #FFFFFF;\">The phenomenon of protecting a region from external electric fields by enclosing it inside a hollow conductor (E_in = 0).</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- SECTION 1: ELECTRIC CHARGES & QUANTIZATION OF CHARGE -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 25px;\">1. Electric Charges &amp; Quantization of Charge</h2>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.08); border-left: 4.5px solid #FF512F; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Electric Charge</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">Electric charge is an intrinsic scalar physical property of fundamental subatomic particles of matter (electrons and protons) that causes them to experience an attractive or repulsive electromagnetic force when placed within electric or magnetic fields.</div>\n  </div>\n\n  <p>Electrostatics is the study of electric forces, fields, and potentials arising from stationary charges. Historical experiments by Benjamin Franklin demonstrated the existence of two distinct types of electric charges: positive charge (acquired by a glass rod rubbed with silk) and negative charge (acquired by an ebonite rod rubbed with cat's fur). Fundamental particles possess invariant charges: an electron carries -e = -1.602 × 10<sup>-19</sup> C, while a proton carries +e = +1.602 × 10<sup>-19</sup> C.</p>\n\n  <p><b>Additivity of Charges:</b> Electric charge is a scalar quantity. The total charge of a physical system containing point charges q₁, q₂, ..., qₙ is the algebraic sum of individual charges: Q_total = q₁ + q₂ + ... + qₙ.</p>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.08); border-left: 4.5px solid #FF512F; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Quantization of Charge</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">The Principle of Quantization of Charge asserts that the total electric charge acquired or possessed by any physical body is always an integral multiple of a basic quantum unit of charge e, represented mathematically as q = ±n e, where n is an integer (n = 1, 2, 3, ...).</div>\n  </div>\n\n  <p>At macroscopic scales where charges involved are on the order of microcoulombs (μC), charge appears continuous because 1 μC contains approximately 6.25 × 10<sup>12</sup> elementary electronic charges. However, at microscopic atomic scales, quantization is strictly discrete and fundamental.</p>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 81, 47, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>Quantization Equation: q = ± n e &nbsp;|&nbsp; e = 1.602 × 10<sup>-19</sup> C &nbsp;|&nbsp; 1 C = 6.25 × 10<sup>18</sup> electrons</b></div>\n\n  <!-- SECTION 2: CONSERVATION OF CHARGE -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">2. Conservation of Charge</h2>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.08); border-left: 4.5px solid #FF512F; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Law of Conservation of Charge</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">The Law of Conservation of Charge states that the net algebraic electric charge of an isolated physical system remains strictly constant over time, regardless of any physical, chemical, or nuclear transformations taking place within the system.</div>\n  </div>\n\n  <p>Electric charge can neither be created nor destroyed in isolation; it can only be transferred from one body to another or generated/annihilated in equal and opposite (+q and -q) pairs. Prominent scientific examples demonstrating charge conservation include:</p>\n\n  <ul style=\"margin-left: 20px; line-height: 1.8;\">\n    <li><b>Pair Production &amp; Annihilation:</b> In high-energy nuclear physics, a high-energy gamma-ray photon (γ) produces an electron (e<sup>-</sup>) and a positron (e<sup>+</sup>): γ → e<sup>-</sup> + e<sup>+</sup>. Net initial charge = 0, net final charge = (-1) + (+1) = 0.</li>\n    <li><b>Radioactive Decay:</b> In the alpha decay of Uranium-238 (<sup>238</sup><sub>92</sub>U → <sup>234</sup><sub>90</sub>Th + <sup>4</sup><sub>2</sub>He), total atomic number (charge in units of e) before decay (92) equals total atomic number after decay (90 + 2 = 92).</li>\n  </ul>\n\n  <!-- SECTION 3: COULOMB'S LAW -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">3. Coulomb's Law - Force Between Two Point Charges</h2>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.08); border-left: 4.5px solid #FF512F; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Coulomb's Law</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">Coulomb's Law states that the electrostatic magnitude of force between two stationary point charges is directly proportional to the product of the magnitudes of the charges and inversely proportional to the square of the distance separating their centers, acting along the line joining them.</div>\n  </div>\n\n  <p>In vacuum (or free space), the magnitude of electrostatic force F between two point charges q₁ and q₂ separated by distance r is:</p>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 81, 47, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>F = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">4π ε<sub>0</sub></span>\n  </span> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">q<sub>1</sub> q<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r<sup>2</sup></span>\n  </span> &nbsp;|&nbsp; <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">4π ε<sub>0</sub></span>\n  </span> = 8.9875 × 10<sup>9</sup> N m<sup>2</sup> C<sup>-2</sup></b></div>\n\n  <p>Here, ε₀ = 8.854 × 10<sup>-12</sup> C² N⁻¹ m⁻² represents the <b>Absolute Permittivity of Free Space</b>. When the charges are immersed in a dielectric medium of permittivity ε, the force reduces to F_med = [1/(4πε)] (q₁ q₂ / r²) = F_vac / K, where K = ε_r = ε / ε₀ is the <b>Dielectric Constant (Relative Permittivity)</b> of the medium.</p>\n\n  <h3 style=\"color: #FF512F; margin-top: 18px;\">(i) Vector Form of Coulomb's Law</h3>\n  <p>Let position vectors of charges q₁ and q₂ be r⃗₁ and r⃗₂. Displacement vector from q₁ to q₂ is r⃗₁₂ = r⃗₂ - r⃗₁. The vector force F⃗₁₂ exerted on q₁ by q₂ is:</p>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 81, 47, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>F⃗<sub>12</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">4π ε<sub>0</sub></span>\n  </span> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">q<sub>1</sub> q<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r<sub>12</sub><sup>2</sup></span>\n  </span> r̂<sub>12</sub> &nbsp; ⇒ &nbsp; F⃗<sub>12</sub> = - F⃗<sub>21</sub></b></div>\n\n  <p>This vector symmetry confirms that Coulomb forces obey <b>Newton's Third Law of Motion</b> and constitute central conservative forces.</p>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #FF512F; border-radius: 16px; padding: 18px; margin: 26px 0; box-shadow: 0 10px 30px rgba(255, 81, 47, 0.25);\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17.5px; margin-bottom: 14px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Coulomb's Law Vector Force & Dielectric Permittivity Model\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 840 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <radialGradient id=\"q1Grad\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#FF8A65\"/>\n      <stop offset=\"100%\" stop-color=\"#FF512F\"/>\n    </radialGradient>\n    <radialGradient id=\"q2Grad\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#00E5FF\"/>\n      <stop offset=\"100%\" stop-color=\"#0284C7\"/>\n    </radialGradient>\n    <marker id=\"arrRed\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#FF512F\"/>\n    </marker>\n  </defs>\n\n  <g transform=\"translate(15, 20)\">\n    <text x=\"195\" y=\"30\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">1. Coulomb's Vector Force Model between Point Charges</text>\n    <circle cx=\"100\" cy=\"210\" r=\"32\" fill=\"url(#q1Grad)\"/>\n    <text x=\"100\" y=\"216\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">+q₁</text>\n\n    <circle cx=\"300\" cy=\"210\" r=\"32\" fill=\"url(#q2Grad)\"/>\n    <text x=\"300\" y=\"216\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">+q₂</text>\n\n    <line x1=\"68\" y1=\"210\" x2=\"15\" y2=\"210\" stroke=\"#FF512F\" stroke-width=\"3\" marker-end=\"url(#arrRed)\"/>\n    <text x=\"40\" y=\"195\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">F₂₁ ←</text>\n\n    <line x1=\"332\" y1=\"210\" x2=\"385\" y2=\"210\" stroke=\"#FF512F\" stroke-width=\"3\" marker-end=\"url(#arrRed)\"/>\n    <text x=\"360\" y=\"195\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">→ F₁₂</text>\n\n    <line x1=\"100\" y1=\"270\" x2=\"300\" y2=\"270\" stroke=\"#94A3B8\" stroke-width=\"1.8\" stroke-dasharray=\"4,4\"/>\n    <text x=\"200\" y=\"295\" text-anchor=\"middle\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13.5\">Separation Distance r</text>\n\n    <text x=\"195\" y=\"380\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Repulsive Pair: F₁₂ = - F₂₁ = [ 1 / (4πε₀) ] (q₁ q₂ / r²)</text>\n  </g>\n\n  <line x1=\"415\" y1=\"30\" x2=\"415\" y2=\"450\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n\n  <g transform=\"translate(430, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"390\" height=\"430\" rx=\"12\" fill=\"rgba(15,23,42,0.9)\" stroke=\"#FF512F\" stroke-width=\"1.8\"/>\n    <text x=\"195\" y=\"35\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">2. Permittivity &amp; Dielectric Constant K</text>\n\n    <rect x=\"15\" y=\"60\" width=\"360\" height=\"110\" rx=\"8\" fill=\"rgba(255,81,47,0.08)\" stroke=\"#FF512F\" stroke-width=\"1.2\"/>\n    <text x=\"195\" y=\"85\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Electrostatic Constant in Vacuum (k):</text>\n    <text x=\"195\" y=\"118\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"15.5\" font-weight=\"bold\">1 / (4πε₀) = 8.9875 × 10⁹ N m² C⁻²</text>\n    <text x=\"195\" y=\"148\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"monospace\" font-size=\"13.5\">ε₀ = 8.854 × 10⁻¹² C² N⁻¹ m⁻²</text>\n\n    <rect x=\"15\" y=\"185\" width=\"360\" height=\"110\" rx=\"8\" fill=\"rgba(118,255,3,0.08)\" stroke=\"#76FF03\" stroke-width=\"1.2\"/>\n    <text x=\"195\" y=\"210\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Force in Dielectric Medium (F_med):</text>\n    <text x=\"195\" y=\"245\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"16\" font-weight=\"bold\">F_med = F_vac / K = F_vac / ε_r</text>\n    <text x=\"195\" y=\"275\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"12.5\">✓ Water K = 80: Electrostatic attraction drops to 1/80th!</text>\n\n    <rect x=\"15\" y=\"310\" width=\"360\" height=\"105\" rx=\"8\" fill=\"rgba(0,229,255,0.08)\" stroke=\"#00E5FF\" stroke-width=\"1.2\"/>\n    <text x=\"195\" y=\"335\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Vector Direction Formula:</text>\n    <text x=\"195\" y=\"365\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"14.5\">F⃗₁₂ = [ 1 / (4πε₀) ] (q₁ q₂ / r₁₂²) r̂₁₂</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 14px; line-height: 1.5; font-weight: 500;\">\n      💡 Vector force directions F₁₂ = -F₂₁ between point charges and reduction of electrostatic force in dielectric medium K.\n    </div>\n  </div>\n\n  <!-- SECTION 4: SUPERPOSITION PRINCIPLE & CONTINUOUS CHARGE DISTRIBUTION -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">4. Forces Between Multiple Charges, Superposition Principle &amp; Continuous Charge Distribution</h2>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.08); border-left: 4.5px solid #FF512F; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Principle of Superposition</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">The Principle of Superposition states that when multiple point charges interact, the total electrostatic force exerted on any given charge equals the vector sum of individual forces exerted on it by all other charges taken one at a time, unaffected by the presence of other charges.</div>\n  </div>\n\n  <p>For a system of N point charges q₁, q₂, ..., qₙ, the total net force F⃗₁ acting on charge q₁ is:</p>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 81, 47, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>F⃗<sub>1</sub> = F⃗<sub>12</sub> + F⃗<sub>13</sub> + ... + F⃗<sub>1N</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">q<sub>1</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">4π ε<sub>0</sub></span>\n  </span> ∑<sub>i=2</sub><sup>N</sup> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">q<sub>i</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r<sub>1i</sub><sup>2</sup></span>\n  </span> r̂<sub>1i</sub></b></div>\n\n  <h3 style=\"color: #FF512F; margin-top: 18px;\">(i) Continuous Charge Distributions</h3>\n  <p>When charges are distributed continuously over macroscopic regions, we define three density functions:</p>\n\n  <ul style=\"margin-left: 20px; line-height: 1.8;\">\n    <li><b>Linear Charge Density (λ):</b> Charge per unit length along a line/wire: λ = dq / dl [C m⁻¹]. Total force F⃗ = [q₀ / (4πε₀)] ∫ (λ dl / r²) r̂.</li>\n    <li><b>Surface Charge Density (σ):</b> Charge per unit surface area: σ = dq / dA [C m⁻²]. Total force F⃗ = [q₀ / (4πε₀)] ∫ (σ dA / r²) r̂.</li>\n    <li><b>Volume Charge Density (ρ):</b> Charge per unit volume: ρ = dq / dV [C m⁻³]. Total force F⃗ = [q₀ / (4πε₀)] ∫ (ρ dV / r²) r̂.</li>\n  </ul>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #FF512F; border-radius: 16px; padding: 18px; margin: 26px 0; box-shadow: 0 10px 30px rgba(255, 81, 47, 0.25);\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17.5px; margin-bottom: 14px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Continuous Charge Density Models: Linear (λ), Surface (σ), Volume (ρ)\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 840 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <g transform=\"translate(15, 20)\">\n    <text x=\"405\" y=\"30\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">Continuous Charge Densities: Line (λ), Surface (σ), Volume (ρ)</text>\n\n    <!-- Line Charge λ -->\n    <rect x=\"20\" y=\"60\" width=\"240\" height=\"340\" rx=\"10\" fill=\"rgba(255,81,47,0.08)\" stroke=\"#FF512F\" stroke-width=\"1.5\"/>\n    <text x=\"140\" y=\"90\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">1. Linear Charge (λ)</text>\n    <line x1=\"140\" y1=\"120\" x2=\"140\" y2=\"300\" stroke=\"#FF512F\" stroke-width=\"6\"/>\n    <circle cx=\"140\" cy=\"140\" r=\"4\" fill=\"#FFFFFF\"/>\n    <circle cx=\"140\" cy=\"180\" r=\"4\" fill=\"#FFFFFF\"/>\n    <circle cx=\"140\" cy=\"220\" r=\"4\" fill=\"#FFFFFF\"/>\n    <circle cx=\"140\" cy=\"260\" r=\"4\" fill=\"#FFFFFF\"/>\n    <text x=\"140\" y=\"335\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"15\" font-weight=\"bold\">λ = dq / dl</text>\n    <text x=\"140\" y=\"360\" text-anchor=\"middle\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">SI Unit: C m⁻¹</text>\n    <text x=\"140\" y=\"380\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"12.5\">Thin Wires / Rods</text>\n\n    <!-- Surface Charge σ -->\n    <rect x=\"280\" y=\"60\" width=\"240\" height=\"340\" rx=\"10\" fill=\"rgba(118,255,3,0.08)\" stroke=\"#76FF03\" stroke-width=\"1.5\"/>\n    <text x=\"400\" y=\"90\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">2. Surface Charge (σ)</text>\n    <polygon points=\"320,150 460,130 480,270 340,290\" fill=\"rgba(118,255,3,0.25)\" stroke=\"#76FF03\" stroke-width=\"2\"/>\n    <text x=\"400\" y=\"335\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"15\" font-weight=\"bold\">σ = dq / dA</text>\n    <text x=\"400\" y=\"360\" text-anchor=\"middle\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">SI Unit: C m⁻²</text>\n    <text x=\"400\" y=\"380\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"12.5\">Plane Sheets / Shells</text>\n\n    <!-- Volume Charge ρ -->\n    <rect x=\"540\" y=\"60\" width=\"240\" height=\"340\" rx=\"10\" fill=\"rgba(0,229,255,0.08)\" stroke=\"#00E5FF\" stroke-width=\"1.5\"/>\n    <text x=\"660\" y=\"90\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">3. Volume Charge (ρ)</text>\n    <rect x=\"600\" y=\"140\" width=\"100\" height=\"100\" fill=\"rgba(0,229,255,0.2)\" stroke=\"#00E5FF\" stroke-width=\"2\"/>\n    <polygon points=\"600,140 630,110 730,110 700,140\" fill=\"rgba(0,229,255,0.3)\" stroke=\"#00E5FF\" stroke-width=\"1.5\"/>\n    <polygon points=\"700,140 730,110 730,210 700,240\" fill=\"rgba(0,229,255,0.15)\" stroke=\"#00E5FF\" stroke-width=\"1.5\"/>\n    <text x=\"660\" y=\"335\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"15\" font-weight=\"bold\">ρ = dq / dV</text>\n    <text x=\"660\" y=\"360\" text-anchor=\"middle\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">SI Unit: C m⁻³</text>\n    <text x=\"660\" y=\"380\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"12.5\">Solid Spheres / Dielectrics</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 14px; line-height: 1.5; font-weight: 500;\">\n      💡 3D geometric breakdown of continuous charge distribution functions along wires, surface sheets, and 3D volumes.\n    </div>\n  </div>\n\n  <!-- SECTION 5: ELECTRIC FIELD -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">5. Electric Field &amp; Electric Field Due to a Point Charge</h2>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.08); border-left: 4.5px solid #FF512F; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Electric Field Intensity (E⃗)</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">Electric Field Intensity at a point in space is defined as the electrostatic force experienced per unit positive infinitesimal test charge q₀ placed at that point without disturbing the source charge configuration: E⃗ = lim(q₀→0) (F⃗ / q₀).</div>\n  </div>\n\n  <p>The SI unit of electric field intensity is Newton per Coulomb (N C⁻¹) or Volt per Meter (V m⁻¹). Dimensions are [M L T⁻³ I⁻¹].</p>\n\n  <h3 style=\"color: #FF512F; margin-top: 18px;\">(i) Electric Field Due to a Single Isolated Point Charge</h3>\n  <p>Consider a source point charge Q situated at origin O. The electric field E⃗ at distance r due to Q is derived by placing test charge q₀ at P:</p>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 81, 47, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>E⃗ = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">4π ε<sub>0</sub></span>\n  </span> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Q</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r<sup>2</sup></span>\n  </span> r̂</b></div>\n\n  <p>The field radiates radially outwards for positive source charges (Q > 0) and radially inwards for negative source charges (Q < 0), obeying the spherical inverse square law.</p>\n\n  <!-- SECTION 6: ELECTRIC FIELD LINES -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">6. Electric Field Lines &amp; Their Fundamental Properties</h2>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.08); border-left: 4.5px solid #FF512F; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Electric Field Line</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">An electric field line is a smooth continuous imaginary curve drawn in an electric field such that the tangent drawn at any point on the curve gives the direction of the net electric field vector E⃗ at that point.</div>\n  </div>\n\n  <p>Fundamental properties of electric field lines include:</p>\n\n  <ol style=\"margin-left: 20px; line-height: 1.8;\">\n    <li>Field lines continuously originate from positive charges and terminate on negative charges.</li>\n    <li>Field lines are continuous curves without any breaks in free space.</li>\n    <li><b>Two electric field lines CAN NEVER intersect each other.</b> If they intersected, two tangents could be drawn at the point of intersection, indicating two different directions of net electric field at a single point, which is physically impossible.</li>\n    <li>Field lines do NOT form closed loops because electrostatic field is conservative (∮ E⃗ · dl⃗ = 0).</li>\n    <li>Relative density of field lines represents field magnitude (crowded lines indicate strong field).</li>\n  </ol>\n\n  <!-- SECTION 7: ELECTRIC DIPOLE -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">7. Electric Dipole &amp; Electric Field Due to a Dipole</h2>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.08); border-left: 4.5px solid #FF512F; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Electric Dipole & Dipole Moment (p⃗)</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">An Electric Dipole is a pair of equal and opposite point charges (+q and -q) separated by a small distance 2a. The Electric Dipole Moment vector p⃗ is defined as the product of charge magnitude q and separation vector 2a⃗, directed from negative charge to positive charge: p⃗ = q (2a⃗) [C m].</div>\n  </div>\n\n  <h3 style=\"color: #FF512F; margin-top: 18px;\">(i) Derivation: Electric Field at a Point on the Axial Line of a Dipole</h3>\n  <p>Let point P lie at distance r from dipole center O along the axial line. Field due to +q is E₊ = [1/(4πε₀)] [q / (r-a)²], and field due to -q is E₋ = [1/(4πε₀)] [q / (r+a)²]. Net axial field E_axial = E₊ - E₋:</p>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 81, 47, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>E<sub>axial</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">4π ε<sub>0</sub></span>\n  </span> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2 p r</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">(r<sup>2</sup> - a<sup>2</sup>)<sup>2</sup></span>\n  </span> &nbsp; ⇒ &nbsp; (For r >> a): E<sub>axial</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">4π ε<sub>0</sub></span>\n  </span> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2 p</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r<sup>3</sup></span>\n  </span></b></div>\n\n  <h3 style=\"color: #FF512F; margin-top: 18px;\">(ii) Derivation: Electric Field at a Point on the Equatorial Line of a Dipole</h3>\n  <p>Let point Q lie at distance r from dipole center on the perpendicular bisector (equatorial line). Vertical field components cancel, while horizontal components add up (E_eq = 2 E₊ cos θ):</p>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 81, 47, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>E<sub>eq</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">4π ε<sub>0</sub></span>\n  </span> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">p</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">(r<sup>2</sup> + a<sup>2</sup>)<sup>3/2</sup></span>\n  </span> &nbsp; ⇒ &nbsp; (For r >> a): E<sub>eq</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">4π ε<sub>0</sub></span>\n  </span> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">p</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r<sup>3</sup></span>\n  </span></b></div>\n\n  <p>Comparing axial and equatorial short dipole fields yields the crucial ratio: <b>E_axial = 2 E_eq</b>.</p>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #FF512F; border-radius: 16px; padding: 18px; margin: 26px 0; box-shadow: 0 10px 30px rgba(255, 81, 47, 0.25);\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17.5px; margin-bottom: 14px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Electric Dipole Axial & Equatorial Electric Field Vector Model\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 840 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <g transform=\"translate(15, 20)\">\n    <text x=\"195\" y=\"30\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">1. Dipole Axial Line Field (r &gt;&gt; a)</text>\n    <line x1=\"40\" y1=\"210\" x2=\"350\" y2=\"210\" stroke=\"#475569\" stroke-width=\"2\"/>\n    <circle cx=\"100\" cy=\"210\" r=\"16\" fill=\"#FF512F\"/>\n    <text x=\"100\" y=\"215\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">-q</text>\n    <circle cx=\"180\" cy=\"210\" r=\"16\" fill=\"#00E5FF\"/>\n    <text x=\"180\" y=\"215\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">+q</text>\n\n    <!-- Axial Point P -->\n    <circle cx=\"310\" cy=\"210\" r=\"5\" fill=\"#76FF03\"/>\n    <text x=\"310\" y=\"190\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">Point P (Axial)</text>\n\n    <text x=\"195\" y=\"340\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"monospace\" font-size=\"15\" font-weight=\"bold\">E_axial = [ 1 / (4πε₀) ] (2 p / r³)</text>\n    <text x=\"195\" y=\"375\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13\">Direction: Along Dipole Moment p⃗ (-q to +q)</text>\n  </g>\n\n  <line x1=\"415\" y1=\"30\" x2=\"415\" y2=\"450\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n\n  <g transform=\"translate(430, 20)\">\n    <text x=\"195\" y=\"30\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">2. Dipole Equatorial Line Field (r &gt;&gt; a)</text>\n    <line x1=\"90\" y1=\"280\" x2=\"270\" y2=\"280\" stroke=\"#475569\" stroke-width=\"2\"/>\n    <circle cx=\"120\" cy=\"280\" r=\"16\" fill=\"#FF512F\"/>\n    <text x=\"120\" y=\"285\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">-q</text>\n    <circle cx=\"240\" cy=\"280\" r=\"16\" fill=\"#00E5FF\"/>\n    <text x=\"240\" y=\"285\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">+q</text>\n\n    <!-- Equatorial Point Q -->\n    <line x1=\"180\" y1=\"280\" x2=\"180\" y2=\"100\" stroke=\"#94A3B8\" stroke-dasharray=\"4,4\"/>\n    <circle cx=\"180\" cy=\"110\" r=\"5\" fill=\"#76FF03\"/>\n    <text x=\"180\" y=\"90\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">Point Q (Equatorial)</text>\n\n    <text x=\"195\" y=\"340\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"monospace\" font-size=\"15\" font-weight=\"bold\">E_eq = [ 1 / (4πε₀) ] (p / r³)</text>\n    <text x=\"195\" y=\"375\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"13\">Ratio E_axial / E_eq = 2 : 1</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 14px; line-height: 1.5; font-weight: 500;\">\n      💡 Derivation geometry for dipole field along axial line E_axial = [1/(4πε₀)] (2p/r³) and equatorial line E_eq = [1/(4πε₀)] (p/r³).\n    </div>\n  </div>\n\n  <!-- SECTION 8: TORQUE ON A DIPOLE IN UNIFORM ELECTRIC FIELD -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">8. Torque on a Dipole in a Uniform Electric Field</h2>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.08); border-left: 4.5px solid #FF512F; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Torque on Electric Dipole</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">When an electric dipole of moment p⃗ is placed in a uniform electric field E⃗ at angle θ, equal and opposite forces F⃗ = ±q E⃗ act on charges forming a couple that exerts a restoring torque: τ⃗ = p⃗ × E⃗, with magnitude τ = p E sin θ.</div>\n  </div>\n\n  <p>Net translatory force on the dipole in a uniform electric field is zero (F_net = 0), so the dipole undergoes pure rotation.</p>\n\n  <ul style=\"margin-left: 20px; line-height: 1.8;\">\n    <li><b>Stable Equilibrium (θ = 0°):</b> Dipole aligned parallel to field (τ = 0, Potential Energy U = -p E).</li>\n    <li><b>Unstable Equilibrium (θ = 180°):</b> Dipole aligned anti-parallel to field (τ = 0, Potential Energy U = +p E).</li>\n    <li><b>Maximum Torque (θ = 90°):</b> Dipole perpendicular to field (τ_max = p E).</li>\n  </ul>\n\n  <!-- SECTION 9: ELECTRIC FLUX -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">9. Electric Flux</h2>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.08); border-left: 4.5px solid #FF512F; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Electric Flux (Φ_E)</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">Electric Flux Φ_E through a surface is a scalar measure of the total number of electric field lines crossing normally through that surface area: Φ_E = ∬ E⃗ · dA⃗ = ∬ E dA cos θ [N m² C⁻¹].</div>\n  </div>\n\n  <p>Flux is positive when field lines exit a closed surface (θ < 90°) and negative when field lines enter a closed surface (θ > 90°).</p>\n\n  <!-- SECTION 10: GAUSS'S THEOREM -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">10. Statement of Gauss's Theorem</h2>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.08); border-left: 4.5px solid #FF512F; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Gauss's Theorem / Law</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">Gauss's Theorem states that the total enclosed electric flux Φ_E through any closed three-dimensional Gaussian surface in free space equals 1/ε₀ times the net algebraic electric charge q_enclosed enclosed inside that surface: ∮ E⃗ · dA⃗ = q_enclosed / ε₀.</div>\n  </div>\n\n  <p>Gauss's law is valid for closed surfaces of any arbitrary shape and size. However, it is computationally most powerful when applied to highly symmetric charge distributions (spherical, cylindrical, or planar symmetry).</p>\n\n  <!-- SECTION 11: APPLICATIONS OF GAUSS'S THEOREM -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">11. Applications of Gauss's Theorem</h2>\n\n  <h3 style=\"color: #FF512F; margin-top: 18px;\">(i) Electric Field Due to an Infinitely Long Straight Uniformly Charged Wire</h3>\n  <p>Consider an infinitely long wire of linear charge density λ. Construct a co-axial cylindrical Gaussian surface of radius r and length l. Flux through circular caps is zero. Flux through curved surface Φ_E = E (2π r l) = λ l / ε₀:</p>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 81, 47, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>E = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">λ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2π ε<sub>0</sub> r</span>\n  </span> &nbsp; ⇒ &nbsp; E ∝ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r</span>\n  </span></b></div>\n\n  <h3 style=\"color: #FF512F; margin-top: 18px;\">(ii) Electric Field Due to a Uniformly Charged Infinite Plane Sheet</h3>\n  <p>Consider an infinite plane sheet of surface charge density σ. Construct a cylindrical pillbox Gaussian surface of cross-sectional area A piercing the sheet. Total flux through two end caps Φ_E = 2 E A = σ A / ε₀:</p>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 81, 47, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>E = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">σ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2 ε<sub>0</sub></span>\n  </span> &nbsp; (Uniform & Distance-Independent)</b></div>\n\n  <h3 style=\"color: #FF512F; margin-top: 18px;\">(iii) Electric Field Due to a Uniformly Charged Thin Spherical Shell</h3>\n  <p>Consider a thin spherical shell of radius R carrying total charge Q. Construct a concentric spherical Gaussian surface of radius r:</p>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 81, 47, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>1. Outside Shell (r ≥ R): E<sub>out</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">4π ε<sub>0</sub></span>\n  </span> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Q</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r<sup>2</sup></span>\n  </span> &nbsp;|&nbsp; 2. Inside Shell (r < R): E<sub>in</sub> = 0</b></div>\n\n  <p>Inside the conductor, no charge is enclosed (q_enclosed = 0), so the electric field vanishes completely (E_in = 0). This provides the physical mechanism for <b>Electrostatic Shielding</b>.</p>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #FF512F; border-radius: 16px; padding: 18px; margin: 26px 0; box-shadow: 0 10px 30px rgba(255, 81, 47, 0.25);\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17.5px; margin-bottom: 14px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Gauss's Law Applications: Wire, Sheet & Thin Spherical Shell\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 840 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <g transform=\"translate(15, 20)\">\n    <text x=\"405\" y=\"30\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">Gauss's Law Applications: Wire, Sheet &amp; Thin Spherical Shell</text>\n\n    <!-- App 1: Infinitely Long Wire -->\n    <rect x=\"20\" y=\"60\" width=\"240\" height=\"340\" rx=\"10\" fill=\"rgba(255,81,47,0.08)\" stroke=\"#FF512F\" stroke-width=\"1.5\"/>\n    <text x=\"140\" y=\"90\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">1. Infinite Straight Wire</text>\n    <line x1=\"140\" y1=\"110\" x2=\"140\" y2=\"280\" stroke=\"#FF512F\" stroke-width=\"4\"/>\n    <ellipse cx=\"140\" cy=\"140\" rx=\"40\" ry=\"12\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n    <ellipse cx=\"140\" cy=\"250\" rx=\"40\" ry=\"12\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"1.5\"/>\n    <line x1=\"100\" y1=\"140\" x2=\"100\" y2=\"250\" stroke=\"#00E5FF\" stroke-width=\"1.5\"/>\n    <line x1=\"180\" y1=\"140\" x2=\"180\" y2=\"250\" stroke=\"#00E5FF\" stroke-width=\"1.5\"/>\n    <text x=\"140\" y=\"335\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"15\" font-weight=\"bold\">E = λ / (2πε₀ r)</text>\n    <text x=\"140\" y=\"365\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13\">Cylindrical Gaussian Surface</text>\n\n    <!-- App 2: Infinite Plane Sheet -->\n    <rect x=\"280\" y=\"60\" width=\"240\" height=\"340\" rx=\"10\" fill=\"rgba(118,255,3,0.08)\" stroke=\"#76FF03\" stroke-width=\"1.5\"/>\n    <text x=\"400\" y=\"90\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">2. Infinite Plane Sheet</text>\n    <polygon points=\"340,140 460,120 460,260 340,280\" fill=\"rgba(118,255,3,0.2)\" stroke=\"#76FF03\" stroke-width=\"2\"/>\n    <text x=\"400\" y=\"335\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"15\" font-weight=\"bold\">E = σ / (2ε₀)</text>\n    <text x=\"400\" y=\"365\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"13\">Uniform &amp; Distance Independent!</text>\n\n    <!-- App 3: Thin Spherical Shell -->\n    <rect x=\"540\" y=\"60\" width=\"240\" height=\"340\" rx=\"10\" fill=\"rgba(0,229,255,0.08)\" stroke=\"#00E5FF\" stroke-width=\"1.5\"/>\n    <text x=\"660\" y=\"90\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">3. Thin Spherical Shell</text>\n    <circle cx=\"660\" cy=\"195\" r=\"45\" fill=\"none\" stroke=\"#FF512F\" stroke-width=\"2.5\"/>\n    <circle cx=\"660\" cy=\"195\" r=\"70\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\"/>\n    <text x=\"660\" y=\"315\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"14\">Outside (r ≥ R): E = Q / (4πε₀ r²)</text>\n    <text x=\"660\" y=\"345\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"monospace\" font-size=\"14.5\" font-weight=\"bold\">Inside (r &lt; R): E_in = 0</text>\n    <text x=\"660\" y=\"375\" text-anchor=\"middle\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"12.5\">Electrostatic Shielding Effect</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 14px; line-height: 1.5; font-weight: 500;\">\n      💡 Gaussian surfaces & derived field expressions for infinite wire E=λ/(2πε₀r), infinite sheet E=σ/(2ε₀), and spherical shell E_in=0.\n    </div>\n  </div>\n\n  <!-- QUICK REVISION CHEAT SHEET -->\n  <div style=\"background: rgba(255, 81, 47, 0.05); border: 1.5px solid #FF512F; border-radius: 12px; padding: 18px; margin-top: 35px; margin-bottom: 15px;\">\n    <h2 class=\"text-center\" style=\"color: #FF512F; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">⚡ Quick Revision Cheat Sheet</h2>\n    <p class=\"text-center\" style=\"color: #FF512F; margin: 0 0 16px 0; font-size: 14.5px; text-align: center !important;\">Summary Formulae for Class 12 Unit I: Electric Charges and Fields</p>\n\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 12px; font-size: 14.5px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 4px;'>• Coulomb's Law &amp; Field:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.65; display: block;\">F = [1/(4πε₀)] (q₁ q₂ / r²)<br>E = F/q₀ = [1/(4πε₀)] (Q/r²)</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 4px;'>• Dipole Fields &amp; Torque:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.65; display: block;\">E_axial = [1/(4πε₀)] (2p/r³)<br>E_eq = [1/(4πε₀)] (p/r³)<br>τ⃗ = p⃗ × E⃗ (τ = p E sin θ)</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 4px;'>• Gauss Law Applications:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.65; display: block;\">Wire: E = λ / (2πε₀ r)<br>Sheet: E = σ / (2ε₀)<br>Shell: E_out = Q/(4πε₀ r²), E_in = 0</span>\n      </div>\n    </div>\n  </div>\n\n</div>\n";

